import re

import pytest
from fastapi import Body, FastAPI
from fastapi.exceptions import RequestValidationError
from fastapi.testclient import TestClient

app = FastAPI()


@app.post("/items/")
def create_item(value: str = Body(min_length=5)):
    return {"value": value}


client = TestClient(app)


@pytest.mark.parametrize("value", ["", "abc"])
def test_validation_error_code(value):
    response = client.post("/items/", json=value)

    assert response.status_code == 422
    errors = response.json()["detail"]
    assert len(errors) == 1
    for error in errors:
        assert "code" in error
        assert error["code"].isupper()
        assert re.fullmatch(r"[A-Z][A-Z0-9_]*", error["code"])
        assert error["code"] == "STRING_TOO_SHORT"
        assert error["loc"] == ["body"]
        assert error["msg"] == "String should have at least 5 characters"
        assert error["type"] == "string_too_short"
        assert error["input"] == value
        assert error["ctx"] == {"min_length": 5}


def test_dotted_error_codes_preserve_original_errors():
    errors = [
        {"loc": ["body", "name"], "msg": "Too short", "type": "value_error.any_str.min_length"},
        {"loc": ["body", "count"], "msg": "Invalid integer", "type": "type_error.integer"},
    ]
    exception = RequestValidationError(errors)
    custom_app = FastAPI()

    @custom_app.post("/items/")
    def create_item():
        raise exception

    response = TestClient(custom_app).post("/items/")

    assert response.status_code == 422
    assert response.json() == {
        "detail": [
            {**errors[0], "code": "VALUE_ERROR_ANY_STR_MIN_LENGTH"},
            {**errors[1], "code": "TYPE_ERROR_INTEGER"},
        ]
    }
    assert all("code" not in error for error in exception.errors())
